@log_input_and_output
def verify_average_tput(start_timestamp, duration, direction, throughput, deviation, cell_id):
    """
    Checks whether the average throughput is within given deviation.

    :param start_timestamp: timestamp when data transfer started, format: %H:%M:%S.%f
    :type start_timestamp: str
    :param duration: duration of data transfer, eg. 300s
    :type duration: str
    :param throughput: Amount of data transfer throughput, eg. '558.0 Mbits/sec'
    :type throughput: str
    :param deviation: Percentage of accepted data deviation, eg. '10%'
    :type deviation: str
    :param direction: Transfer direction: can be download or upload, eg. 'dl' or 'ul'
    :type direction: str
    :param cell_id: ID number of the tested cell
    :type cell_id: int

    :raises: AverageThroughputNotWithinDeviation when average
    throughput value is not within deviation limits

    :return: average_tput
    :rtype: float

    """
    target_tput = float(throughput.strip("Mbits/sec"))
    deviation = float(deviation.strip("%")) / 100
    average_tput = calculate_average_tput_from_btslog(
        start_timestamp, duration, direction, cell_id
    )

    lower_limit = target_tput - target_tput * deviation
    upper_limit = target_tput + target_tput * deviation
    if not lower_limit <= average_tput <= upper_limit:
        raise AverageThroughputNotWithinDeviation(
            "Average throughput value {:.2f} Mbist/sec not within deviation limits: {:.2f}"
            " Mbits/sec >= {:.2f} Mbits/sec <= {:.2f} Mbits/sec".format(
                average_tput, lower_limit, target_tput, upper_limit
            )
        )

    return average_tput


def calculate_average_tput_from_btslog(start_timestamp, duration, direction, cell_id):
    """
    Calculates average throughput value based on msgs parsed from btslog.

    :param start_timestamp: timestamp when data transfer started, format: %H:%M:%S.%f
    :type start_timestamp: str
    :param duration: duration of data transfer, eg. 300s
    :type duration: str
    :param direction: Transfer direction: can be download or upload, eg. 'dl' or 'ul'
    :type direction: str
    :param cell_id: ID number of the tested cell
    :type cell_id: int

    :return: average_tput
    :rtype: float

    """
    delta_seconds = int(duration.strip("s")) * 0.9
    start_timestamp = datetime.strptime(start_timestamp, "%H:%M:%S.%f")
    stop_timestamp = start_timestamp + timedelta(seconds=delta_seconds * 0.9)

    tput_values_in_bytes = parse_tput_msgs_from_btslog(
        start_timestamp, stop_timestamp, direction, cell_id
    )
    tput_values_in_megabits = [
        tput * 7.6294 * 10**-6 for tput in tput_values_in_bytes
    ]
    log_env_state(str(tput_values_in_megabits))
    try:
        average_tput = sum(tput_values_in_megabits) / len(tput_values_in_megabits)
    except ZeroDivisionError:
        raise ThroughputMsgsNotFoundInBtslog("No proper messages concerning transfer found in btslog!"
                                             "Check whether your swconfig is correct and that btslog "
                                             "collection is started properly.")

    return average_tput


def parse_tput_msgs_from_btslog(start_timestamp, stop_timestamp, direction, cell_id):
    """
    Parses messages from btslog concerning throughput in given direction.

    :param start_timestamp: timestamp when data transfer started, format: %H:%M:%S.%f
    :type start_timestamp: datetime
    :param stop_timestamp: timestamp when data transfer finished, format: %H:%M:%S.%f
    :type stop_timestamp: datetime
    :param direction: Transfer direction: can be download or upload, eg. 'dl' or 'ul'
    :type direction: str
    :param cell_id: ID number of the tested cell
    :type cell_id: int

    :return: tput_values
    :rtype: list(int)
    """
    logfiles = _get_all_btslog_files()

    tput_values = []
    for logfile in logfiles:
        tput_values.extend(
            parse_tput_values(logfile, start_timestamp, stop_timestamp, direction, cell_id)
        )
    return tput_values


def parse_tput_values(logfile_path, start_timestamp, stop_timestamp, direction, cell_id):
    """
    Parses messages from btslog concerning throughput in given logfile.

    :param logfile_path: path to the file containing btslog
    :type logfile_path: str
    :param start_timestamp: timestamp when data transfer started, format: %H:%M:%S.%f
    :type start_timestamp: datetime
    :param stop_timestamp: timestamp when data transfer finished, format: %H:%M:%S.%f
    :type stop_timestamp: datetime
    :param direction: Transfer direction: can be download or upload, eg. 'dl' or 'ul'
    :type direction: str
    :param cell_id: ID number of the tested cell
    :type cell_id: int

    :return: tput_msgs
    :rtype: list(int)
    """
    tput_msgs = []

    with codecs.open(logfile_path, "r", encoding='utf-8', errors='ignore') as log_file:
        for line in log_file.readlines():
            if direction == "dl":
                if "DL-RLC numOfBearers:1" in line:
                    timestamp = datetime.strptime(line.split(" ")[2], "%H:%M:%S.%f")
                    if start_timestamp <= timestamp <= stop_timestamp:
                        for index, element in enumerate(line.split(" ")):
                            if "inB:" in element:
                                tput_msgs.append(int(element.split(":")[-1].strip(",")))

            if direction == "ul":
                if "UlCounterUpdate.cpp:20/UL" in line or "UlCounterUpdate.cpp:21/UL" in line:
                    if str(cell_id) in line:
                        timestamp = datetime.strptime(line.split(" ")[2], "%H:%M:%S.%f")
                        if start_timestamp <= timestamp <= stop_timestamp:
                            tput_msgs.append(int(line.split(" ")[10]))

    return tput_msgs


def verify_if_params_have_expected_values(start_timestamp, should_exist=True, **parameters):
    """
    Verifies if params in btslog have expected values
    :param start_timestamp: timestamp when data transfer started, format: %H:%M:%S.%f
    :type start_timestamp: str
    :param should_exist: indicates whether the param we are looking for should exist in btslog
    :type should_exist: bool
    :param parameters: parameter name as a key and its value as value
    :type parameters: dict
    :raises BtslogVerificationFailed: if param does not match the expected value or could be found
    """
    logfiles = _get_all_btslog_files()
    start_timestamp = datetime.strptime(start_timestamp, "%H:%M:%S.%f")

    start_params = parameters.copy()
    for logfile in logfiles:
        with codecs.open(logfile, "r", encoding='utf-8', errors='ignore') as f:
            for line in f.readlines():
                _verify_if_param_exists_and_have_expected_value(parameters, start_timestamp, line)

    if parameters and should_exist or not parameters and not should_exist:
        raise BtslogVerificationFailed(
            "Parameters {} should{} exist in btslog".format(start_params, "" if should_exist else " not")
        )


@log_input_and_output
def check_if_message_exists(msg, start_timestamp, stop_timestamp):
    """
    Parses all btslog files located at "/tmp/btslog2/" path and checks if message appeared in
    particular timestamp scope.

    :param msg: message content to be found
    :type msg: str
    :param start_timestamp: first timestamp as beginning of message search, format: %H:%M:%S.%f
    :type start_timestamp: datetime
    :param stop_timestamp: last timestamp as ending of message search, format: %H:%M:%S.%f
    :type stop_timestamp: datetime
    :return: True if message exists in particular timestamp range, False otherwise
    :rtype: bool
    """
    logfiles = _get_all_btslog_files()
    start_timestamp = datetime.strptime(start_timestamp, "%H:%M:%S.%f")
    stop_timestamp = datetime.strptime(stop_timestamp, "%H:%M:%S.%f")

    for logfile in logfiles:
        if _verify_if_msg_exists_in_file(msg, logfile, start_timestamp, stop_timestamp):
            return True
    return False


@log_input_and_output
def verify_if_custom_string_exists_in_custom_log_directory(custom_str, custom_log_path):
    """
    Verifies if custom string exists in any .LOG or .log file in "custom_log_path" directory.
    If not raises an exception.

    :param custom_str: custom string to be found
    :type custom_str: str
    :param custom_log_path: custom path to .LOG or .log files, format: /custom/path/
    :type custom_log_path: str
    :return: True if custom string exists at least once in any file
    :rtype: bool
    :raises StringNotFoundInLogFile: if custom string is not found in any .LOG or .log file
    """

    if not is_custom_string_in_custom_log_directory(custom_str, custom_log_path):
        raise StringNotFoundInLogFile("String '{}' not found in .LOG/.log files located at {}.".format(
            custom_str, custom_log_path)
        )

    return True


@log_input_and_output
def is_custom_string_in_custom_log_directory(custom_str, custom_log_path):
    """
    Parses all files with .LOG and .log extension located at "custom_log_path" and checks if given string appeared.

    :param custom_str: custom string to be found
    :type custom_str: str
    :param custom_log_path: custom path to .LOG or .log files, format: /custom/path/
    :type custom_log_path: str
    :return: True if custom string exists at least once in any file, False otherwise
    :rtype: bool
    """
    logfiles_paths = _get_paths_to_all_log_files_from_custom_path(custom_log_path)

    for logfile in logfiles_paths:
        if _is_custom_str_in_file(custom_str, logfile):
            return True
    return False


