@log_input_and_output
def check_L2RtPoolDeployment_parameters(parameters_to_check, start_timestamp, stop_timestamp):
    """
    Checks if provided L2RtPoolDeployment parameters (parameters_to_check) exist in BTSLog files (located under
    "/tmp/btslog2/" path) and have proper names and values.

    :param parameters_to_check: parameters dict that should exist in BTSLog file, e.g.:
                                {'slowPrbPoolingFddFr1EnhAllowed': 'false',
                                'spatialStreamPoolingAllowed': 'false',}
    :type parameters_to_check: dict
    :param start_timestamp: first timestamp as beginning of message search, format: %H:%M:%S.%f
    :type start_timestamp: datetime
    :param stop_timestamp: last timestamp as ending of message search, format: %H:%M:%S.%f
    :type stop_timestamp: datetime

    :raises ParameterNotFound: if parameter to check is not found in syslog file
    :raises IncorrectParameterName: if parameter has incorrect name
    :raises IncorrectParameterValue: if parameter has incorrect value
    """
    logfiles = _get_all_btslog_files()
    start_timestamp = datetime.strptime(start_timestamp, "%H:%M:%S.%f")
    stop_timestamp = datetime.strptime(stop_timestamp, "%H:%M:%S.%f")

    for param_name, param_value in parameters_to_check.items():
        for logfile in logfiles:
            result = _search_msg_in_file_using_regex_pattern(regex_pattern=rf"{param_name}: boolean = (false|true)"
                                                                           f"(,|{'}'}|\\)|])",
                                                             logfile_path=logfile, start_timestamp=start_timestamp,
                                                             stop_timestamp=stop_timestamp, ignore_case=True)
            if result is not None:
                break

        if result is not None:
            _verify_L2RtPoolDeployment_parameter_found_in_btslog_file(expected_parameter_name=param_name,
                                                                      expected_parameter_value=param_value,
                                                                      found_parameter=result)
        else:
            raise ParameterNotFound(f"Parameter '{param_name}' is not found in BTSLog file")


