@log_input_and_output
def get_information_with_phase_error_presence_in_syslog(logfile_path):
    """
    Gets information with presence of phase error prints in syslog
    :param logfile_path: list of strings containing paths to logs
    :type logfile_path:list of str
    :return: information, if phase error prints were found with values of phase errors,
    otherwise information that no phase error prints were found.
    :rtype: str
    """
    log_lines = []
    phase_error = "phase error function"
    log_names = []
    for log in logfile_path:
        with codecs.open(log, "r", encoding='utf-8', errors='ignore') as log_file:
            for line in log_file.readlines():
                if phase_error in line:
                    log_lines.append(line)
                    current_log_name = f"{log.split('/')[-1]}"
                    if current_log_name not in log_names:
                        log_names.append(current_log_name)
    if log_lines:
        values = _get_values_of_phase_errors(log_lines)
        return f"HPF value: {values[0]} and previous power on value: {values[1]} were found in syslogs: {log_names} "\
               "If HPF value = 0 and time since previous power on < 1h 20 min " \
               "consider to add that information in potential pronto for FID:10 "\
               "otherwise please check syslog manually if values '-' are visible"
    else:
        return "Syslog doesn't contain phase error function prints, "\
               "manual check of logs might be needed to check why "\
               "FID:10 was reported"


def filter_syslog(syslog_paths, filters=None, time_type='local', start_time=None, stop_time=None, write_to_file_path=None):
    """
    Filters syslog lines based on given parameters.

    :param syslog_paths: Path(s) to syslog file.
    :type syslog_paths: str or list of str
    :param filters: filter rules to be applied to syslog lines.
                    A filter rule can be either:
                    - A simple string, which checks for its presence in the line. e.g. filters = 'OneWayDelayMeasurement'.
                    - A compound filter containing multiple substrings separated by '&&'. filters = 'OneDelayMeasurement&&createPeriodicMeasurement'.
                      In this case, all substrings must be present in the line.
                    - A list of filter rules. In this case, the line must match at least one filter rule.
                      e.g. filters = ['OneWay', 'handle&&SessionReq']
    :type filters: str or list of str
    :param time_type: Type of time in syslog line, can be 'local' (timezone set on VM) or 'utc'. Defaults to 'local'.
    :type time_type: str
    :param start_time: First time as beginning of message search.
    :type start_time: datetime (mandatory: year, month, day, hour, minute, second, microsecond)
    :param stop_time: Last time as ending of message search.
    :type stop_time: datetime (mandatory: year, month, day, hour, minute, second, microsecond)
    :param write_to_file_path: Path to the file e.g. '/home/ute/filtered_syslog.txt' where filtered syslog lines will be saved (optional).
                               If not provided, lines will not be saved. Defaults to None.
    :type write_to_file_path: None or str
    :return: Generator object yielding syslog lines.
    :rtype: Iterator[str]
    """
    filtered, filtered_backup = itertools.tee(_filter_syslog(syslog_paths, filters, time_type, start_time, stop_time))
    if write_to_file_path:
        with open(write_to_file_path, 'w') as file:
            for line in filtered_backup:
                file.write(line)

    return filtered


def get_time_from_line(log_line, time_type='local'):
    """
    Gets 'local' or 'utc' time from syslog line.
    :param log_line: line from syslog (btslog2)
    :type log_line: str
    :param time_type: type of time in syslog line, can be 'local' (timezone set on VM) or 'utc'. Defaults to 'local'
    :type time_type: str
    :return: local or utc time from syslog line e.g. in syslog '19.02 15:47:40.255' or '<2025-02-19T14:46:15.082036Z>'
    :rtype: datetime
    :raises TimeExtractionError if time not found in syslog line
    """
    return _get_time_from_line(log_line=log_line, time_type=time_type)


